"""Shared decoding engine and output sanitization for all Machine Translation models.

Supports batched greedy generation and temperature/top-p nucleus sampling with left-padding
for decoder-only models and output post-processing.
"""

import logging
import re
import time
from typing import Any, Dict, List, Optional, Tuple

import torch
from tqdm import tqdm

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

# Common unwanted prefixes generated by instruction-tuned models
PREFIX_REGEX = re.compile(
    r"^(?:(?:hindi|translation|english|hindi translation|target|output|answer)\s*[:：\-–—]\s*)+",
    re.IGNORECASE,
)
DEV_PREFIX_REGEX = re.compile(
    r"^(?:(?:हिंदी|अनुवाद|उत्तर)\s*[:：\-–—]\s*)+",
    re.IGNORECASE,
)


def clean_generated_output(raw_text: str) -> Tuple[str, bool]:
    """Post-process raw decoder output into clean Hindi translation text.

    Why post-processing is needed for viva:
    Even with instruction tuning, decoder-only LLMs may occasionally echo prompt prefixes
    (e.g., 'Hindi: ' or 'Translation: ') or generate chat conversational filler.
    This function cleans common formatting artifacts while logging how many outputs required cleaning.

    Returns:
        (cleaned_text, was_modified_flag)
    """
    if not raw_text:
        return "", False

    original = raw_text.strip()
    cleaned = original

    # Strip markdown code blocks if any
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```[a-zA-Z]*\n?", "", cleaned)
        cleaned = re.sub(r"\n?```$", "", cleaned)

    # Take the first non-empty line (prevents multi-paragraph hallucination)
    lines = [line.strip() for line in cleaned.split("\n") if line.strip()]
    cleaned = lines[0] if lines else ""

    # Strip prefixes in English or Devanagari
    new_cleaned = PREFIX_REGEX.sub("", cleaned).strip()
    new_cleaned = DEV_PREFIX_REGEX.sub("", new_cleaned).strip()

    was_modified = new_cleaned != original
    return new_cleaned, was_modified


@torch.no_grad()
def generate_hf_causal_lm(
    model: Any,
    tokenizer: Any,
    prompts: List[str],
    batch_size: int = 16,
    max_new_tokens: int = 192,
    temperature: float = 0.0,
    top_p: float = 0.95,
    seed: int = 42,
) -> Tuple[List[str], float, int]:
    """Batched autoregressive generation for Decoder-Only models (LLaMA & Gemma).

    CRITICAL FOR T4 & BATCHING:
    Requires tokenizer.padding_side = 'left' so that position embeddings align
    identically across variable-length prompts.
    """
    model.eval()
    device = next(model.parameters()).device

    # Ensure left padding
    original_padding_side = tokenizer.padding_side
    tokenizer.padding_side = "left"
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token

    # Collect all valid stop token IDs (CRITICAL for Gemma <end_of_turn> and LLaMA <|eot_id|>)
    stop_ids = set()
    if tokenizer.eos_token_id is not None:
        if isinstance(tokenizer.eos_token_id, list):
            stop_ids.update(tokenizer.eos_token_id)
        else:
            stop_ids.add(tokenizer.eos_token_id)

    # Check for Gemma turn terminator (<end_of_turn>)
    eot_id = tokenizer.convert_tokens_to_ids("<end_of_turn>")
    if eot_id is not None and eot_id != tokenizer.unk_token_id:
        stop_ids.add(eot_id)

    # Check for LLaMA turn terminator (<|eot_id|>)
    llama_eot = tokenizer.convert_tokens_to_ids("<|eot_id|>")
    if llama_eot is not None and llama_eot != tokenizer.unk_token_id:
        stop_ids.add(llama_eot)

    eos_token_list = list(stop_ids) if stop_ids else tokenizer.eos_token_id

    do_sample = temperature > 0.0
    gen_kwargs: Dict[str, Any] = {
        "max_new_tokens": max_new_tokens,
        "do_sample": do_sample,
        "pad_token_id": tokenizer.pad_token_id,
        "eos_token_id": eos_token_list,
    }
    if do_sample:
        gen_kwargs["temperature"] = float(temperature)
        gen_kwargs["top_p"] = float(top_p)
        torch.manual_seed(seed)

    all_hypotheses: List[str] = []
    cleaned_count = 0

    start_time = time.perf_counter()

    for i in tqdm(range(0, len(prompts), batch_size), desc="Generating translations", leave=False):
        batch_prompts = prompts[i : i + batch_size]
        inputs = tokenizer(batch_prompts, return_tensors="pt", padding=True, truncation=True)
        inputs = {k: v.to(device) for k, v in inputs.items()}

        input_lengths = inputs["input_ids"].shape[1]

        outputs = model.generate(**inputs, **gen_kwargs)

        # Slice off prompt tokens to obtain assistant tokens only
        generated_tokens = outputs[:, input_lengths:]
        decoded_batch = tokenizer.batch_decode(generated_tokens, skip_special_tokens=True)

        for raw_pred in decoded_batch:
            clean_pred, was_mod = clean_generated_output(raw_pred)
            all_hypotheses.append(clean_pred)
            if was_mod:
                cleaned_count += 1

    total_time = time.perf_counter() - start_time

    # Restore tokenizer setting
    tokenizer.padding_side = original_padding_side

    return all_hypotheses, total_time, cleaned_count


@torch.no_grad()
def generate_hf_seq2seq(
    model: Any,
    tokenizer: Any,
    inputs_text: List[str],
    batch_size: int = 16,
    max_length: int = 128,
    temperature: float = 0.0,
    top_p: float = 0.95,
    seed: int = 42,
) -> Tuple[List[str], float, int]:
    """Batched generation for Pretrained Seq2Seq models (mT5-small)."""
    model.eval()
    device = next(model.parameters()).device

    do_sample = temperature > 0.0
    gen_kwargs: Dict[str, Any] = {
        "max_length": max_length,
        "do_sample": do_sample,
    }
    if do_sample:
        gen_kwargs["temperature"] = float(temperature)
        gen_kwargs["top_p"] = float(top_p)
        torch.manual_seed(seed)

    all_hypotheses: List[str] = []
    cleaned_count = 0

    start_time = time.perf_counter()

    for i in range(0, len(inputs_text), batch_size):
        batch_texts = inputs_text[i : i + batch_size]
        inputs = tokenizer(
            batch_texts, return_tensors="pt", padding=True, truncation=True, max_length=max_length
        )
        inputs = {k: v.to(device) for k, v in inputs.items()}

        outputs = model.generate(**inputs, **gen_kwargs)
        decoded_batch = tokenizer.batch_decode(outputs, skip_special_tokens=True)

        for raw_pred in decoded_batch:
            clean_pred, was_mod = clean_generated_output(raw_pred)
            all_hypotheses.append(clean_pred)
            if was_mod:
                cleaned_count += 1

    total_time = time.perf_counter() - start_time
    return all_hypotheses, total_time, cleaned_count
